/** State of one node on a part's dot grid. */
export type NodeState = 'hole' | 'solid' | 'slot';

/** A non-empty node. Empty nodes are simply absent. Coordinates are grid indices. */
export interface PartNode {
  x: number;
  y: number;
  s: NodeState;
}

export type PartCategory = 'straight' | 'short' | 'disc' | 'slotted' | 'shape' | 'custom';

export interface PartDef {
  id: string;
  name: string;
  category: PartCategory;
  nodes: PartNode[];
  /** Hole pitch override in mm; undefined = sheet default. */
  pitch?: number;
  /** Built-in parts are regenerated by the app and can't be edited (duplicate them instead). */
  builtin?: boolean;
}

export type AcrylicColour = 'green' | 'orange' | 'pink' | 'yellow' | 'blue';

export type SheetSize = 'A5' | 'A4' | 'A3';

export interface Settings {
  /** Stick width, mm. */
  width: number;
  /** Default hole pitch, mm. */
  pitch: number;
  /** Finished hole diameter, mm (before kerf compensation). */
  holeDiameter: number;
  /** Slot width, mm (before kerf compensation). */
  slotWidth: number;
  /** Laser kerf, mm. Applied to holes and slots only (outlines share edges). */
  kerf: number;
  /** Radius of fillets in inside (concave) corners, mm. */
  filletRadius: number;
  sheet: SheetSize;
  landscape: boolean;
  /** Margin on every side, mm. */
  margin: number;
  fill: FillSettings;
  /** Acrylic colour used for the on-screen preview only. */
  acrylic: AcrylicColour;
}

export interface FillSettings {
  enabled: boolean;
  seed: number;
  minLength: number;
  maxLength: number;
  discs: boolean;
}

/** Quantities keyed by part id. */
export type Bin = Record<string, number>;

/** Orientation: quarter turns (0–3) then optional mirror about the vertical axis. */
export interface Orientation {
  rot: 0 | 1 | 2 | 3;
  mirror: boolean;
}

export interface Placement {
  partId: string;
  /** Top-left of the part's bounding box on the sheet, in µm. */
  x: number;
  y: number;
  orient: Orientation;
  /** True for pieces added by the random fill. */
  filler?: boolean;
}

export interface Project {
  format: 'stickleback';
  version: 1;
  saved: string;
  settings: Settings;
  parts: PartDef[];
  bin: Bin;
  placements?: Placement[];
}
